CREATE TABLE IF NOT EXISTS state (id INTEGER PRIMARY KEY CHECK(id=1), body TEXT NOT NULL, locked_until INTEGER NOT NULL DEFAULT 0, owner TEXT);
CREATE TABLE IF NOT EXISTS events (id INTEGER PRIMARY KEY AUTOINCREMENT, ts INTEGER NOT NULL, kind TEXT NOT NULL, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS credentials (name TEXT PRIMARY KEY, sealed TEXT NOT NULL, expires TEXT NOT NULL DEFAULT '', disabled INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS market_signals (id TEXT PRIMARY KEY, asset TEXT NOT NULL, grp TEXT NOT NULL, dir INTEGER NOT NULL, ts INTEGER NOT NULL, status TEXT NOT NULL, r REAL, closed_ts INTEGER, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS market_state (id INTEGER PRIMARY KEY CHECK(id=1), body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS throttle (ip TEXT PRIMARY KEY, window INTEGER NOT NULL, count INTEGER NOT NULL);
